import React, { useCallback, useEffect, useState } from 'react';
import { RefreshControl, Text, View } from 'react-native';
import { Redirect, router } from 'expo-router';
import { formatCount, Stat } from '../../../components/stat';
import { ErrorText, Page, PageHeader, SectionCard, Segmented, Toolbar, styles } from '../../../components/ui';
import { useCanModerate } from '../../../components/mod';
import { colors, fs } from '../../../lib/theme';
import { getGaStats, type GaStats } from '../../../lib/api';
import { dailyEventTotals, getAppAnalytics, namedEventTotals, screenLabel, type AppAnalyticsSummary } from '../../../lib/analytics';

const SITES = { nycpprc: 'nycpprc.org', gnosis: 'gnosis.health', app: 'App' } as const;
const RANGES = [7, 28, 90];

function Bars({ data, field }: { data: GaStats['series']; field: 'users' | 'sessions' | 'views' }) {
  const max = Math.max(1, ...data.map((d) => d[field]));
  return (
    <View style={{ flexDirection: 'row', alignItems: 'flex-end', height: 90, gap: 1 }}>
      {data.map((d) => (
        <View key={d.date} style={{ flex: 1, height: `${(d[field] / max) * 100}%`, minHeight: 1, backgroundColor: colors.navy, opacity: 0.8 }} />
      ))}
    </View>
  );
}

function CountBars({ data }: { data: { date: string; total: number }[] }) {
  const max = Math.max(1, ...data.map((d) => d.total));
  return (
    <View style={{ flexDirection: 'row', alignItems: 'flex-end', height: 90, gap: 1 }}>
      {data.map((d) => (
        <View key={d.date} style={{ flex: 1, height: `${(d.total / max) * 100}%`, minHeight: d.total ? 2 : 1, backgroundColor: colors.navy, opacity: 0.8 }} />
      ))}
    </View>
  );
}

function ProductEvents({ data }: { data: AppAnalyticsSummary }) {
  const totals = namedEventTotals(data.totals);
  const days = dailyEventTotals(data.series);
  return (
    <SectionCard title={`Tracked events · last ${data.days} days`}>
      <Text style={[styles.muted, { fontSize: fs(13), marginBottom: 12 }]}>
        Recorded in the app. {formatCount(data.events)} {data.events === 1 ? 'event' : 'events'} from {formatCount(data.people)} {data.people === 1 ? 'person' : 'people'}.
      </Text>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10 }}>
        {totals.map((row) => (
          <Stat key={row.name} label={row.label} value={row.count} note={`${formatCount(row.people)} ${row.people === 1 ? 'person' : 'people'}`} />
        ))}
      </View>
      {data.events === 0 ? <Text style={[styles.muted, { marginTop: 12 }]}>No events in this range yet.</Text> : (
        <View style={{ marginTop: 14 }}>
          <Text style={[styles.fieldLabel, { marginBottom: 6 }]}>Daily events</Text>
          <CountBars data={days} />
        </View>
      )}
      <View style={{ marginTop: 14 }}>
        <Text style={[styles.fieldLabel, { marginBottom: 6 }]}>Screens</Text>
        {!data.screens.length ? <Text style={styles.muted}>No screen views in this range yet.</Text> : data.screens.map((row) => {
          const max = Math.max(1, ...data.screens.map((s) => Number(s.views) || 0));
          return (
            <View key={row.screen} style={{ paddingVertical: 4 }}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 8 }}>
                <Text style={[styles.body, { flex: 1, fontSize: fs(14) }]} numberOfLines={1}>{screenLabel(row.screen)}</Text>
                <Text style={[styles.body, { fontSize: fs(14) }]}>{formatCount(row.views)}</Text>
              </View>
              <View style={{ height: 3, width: `${(row.views / max) * 100}%`, backgroundColor: colors.line, marginTop: 2 }} />
            </View>
          );
        })}
      </View>
    </SectionCard>
  );
}

function Table({ title, rows }: { title: string; rows: [string, number][] }) {
  const max = Math.max(1, ...rows.map((r) => r[1]));
  return (
    <SectionCard title={title}>
      {!rows.length ? <Text style={styles.muted}>No data.</Text> : null}
      {rows.map(([k, v]) => (
        <View key={k} style={{ paddingVertical: 4 }}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 8 }}>
            <Text style={[styles.body, { flex: 1, fontSize: fs(14) }]} numberOfLines={1}>{k}</Text>
            <Text style={[styles.body, { fontSize: fs(14) }]}>{formatCount(v)}</Text>
          </View>
          <View style={{ height: 3, width: `${(v / max) * 100}%`, backgroundColor: colors.line, marginTop: 2 }} />
        </View>
      ))}
    </SectionCard>
  );
}

export default function AnalyticsTab() {
  const { ready, ok } = useCanModerate();
  const [site, setSite] = useState<keyof typeof SITES>('nycpprc');
  const [days, setDays] = useState(28);
  const [d, setD] = useState<GaStats | null>(null);
  const [app, setApp] = useState<AppAnalyticsSummary | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [appErr, setAppErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    setBusy(true); setErr(null); setAppErr(null);
    const wantApp = site === 'app';
    if (!wantApp) setApp(null);
    const ga = getGaStats(site, days).then(setD).catch((e: any) => { setErr(e.message); setD(null); });
    const product = wantApp
      ? getAppAnalytics(days).then(setApp).catch((e: any) => { setAppErr(e.message); setApp(null); })
      : Promise.resolve();
    await Promise.all([ga, product]);
    setBusy(false);
  }, [site, days]);
  useEffect(() => { if (ok) load(); }, [ok, load]);

  if (!ready) return <View style={{ flex: 1, backgroundColor: colors.paper }} />;
  if (!ok) return <Redirect href="/me" />;
  const sum = (f: 'users' | 'sessions' | 'views') => (d ? d.series.reduce((a, r) => a + r[f], 0) : 0);
  const keyTotals = d ? Object.entries(d.keyEvents).map(([k, v]) => [k, Object.values(v).reduce((a, b) => a + b, 0)] as [string, number]) : [];
  const subtitle = site === 'app'
    ? (app ? `App · last ${app.days} days · ${formatCount(app.people)} ${app.people === 1 ? 'person' : 'people'}` : 'App')
    : (d ? `${SITES[site]} · last ${d.days} days · updated ${new Date(d.generatedAt).toLocaleString()}` : SITES[site]);

  return (
    <Page refreshControl={<RefreshControl refreshing={busy} onRefresh={load} />}>
      <Text onPress={() => router.navigate('/me')} accessibilityRole="link" style={[styles.link, { fontSize: fs(13) }]}>Back to profile</Text>
      <PageHeader icon="bar-chart" eyebrow="Analytics" title={site === 'app' ? 'App analytics' : 'Site traffic'} subtitle={subtitle} />
      <Toolbar>
        <Segmented value={site} onChange={setSite} options={(Object.keys(SITES) as (keyof typeof SITES)[]).map((s) => ({ value: s, label: SITES[s] }))} />
        <Segmented value={days} onChange={setDays} options={RANGES.map((n) => ({ value: n, label: `${n}d` }))} />
      </Toolbar>
      {site === 'app' ? <ErrorText>{appErr}</ErrorText> : null}
      {site === 'app' && busy && !app ? <Text style={styles.muted}>Loading app events…</Text> : null}
      {site === 'app' && app ? <ProductEvents data={app} /> : null}
      <ErrorText>{err}</ErrorText>
      {busy && !d ? <Text style={styles.muted}>Loading…</Text> : null}
      {d ? (
        <>
          <View style={{ flexDirection: 'row', gap: 10 }}>
            {([['Users', 'users'], ['Sessions', 'sessions'], ['Page views', 'views']] as const).map(([label, f]) => (
              <Stat key={f} label={label} value={sum(f)} style={{ flex: 1 }} />
            ))}
          </View>
          {d.product ? (
            <SectionCard title={`App activity · last ${d.days} days`}>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10 }}>
                {([['New members', d.product.newProfiles], ['Messages sent', d.product.messages], ['Total members', d.product.totalProfiles], ['Rooms', d.product.rooms], ['Meetup-linked', d.product.meetupLinked]] as const).map(([label, v]) => (
                  <Stat key={label} label={label} value={v} />
                ))}
              </View>
            </SectionCard>
          ) : null}
          <SectionCard title={site === 'app' ? 'Daily users (/app web)' : 'Daily users'}><Bars data={d.series} field="users" /></SectionCard>
          <Table title="Key events" rows={keyTotals} />
          <Table title="Traffic sources" rows={d.sources.map((s) => [s.name, s.sessions])} />
          <Table title="Top pages (views)" rows={d.pages.map((p) => [p.path, p.views])} />
          <Table title="Countries (users)" rows={d.countries.map((c) => [c.name, c.users])} />
        </>
      ) : null}
    </Page>
  );
}
